{"command": "THREAD_IDS="088510272662486e 0d9fedd1eb434511 251e98200d224269 2f8eca5ebcf749eb 3d1a9eca984f467d 4f35886548c34667 51cd7ef6e6c84784 54bdda91f8844b54"
for tid in $THREAD_IDS; do
  echo "=== THREAD: $tid ==="
  gws gmail users threads get --params "{\"userId\": \"me\", \"id\": \"$tid\"}" 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
for msg in data.get('messages', []):
    headers = {h['name']: h['value'] for h in msg['payload']['headers']}
    print(f\"From: {headers.get('From','')}\")
    print(f\"To: {headers.get('To','')}\")
    print(f\"Subject: {headers.get('Subject','')}\")
    print(f\"Date: {headers.get('Date','')}\")
    # Get body
    body = ''
    if 'parts' in msg['payload']:
        for part in msg['payload']['parts']:
            if part.get('mimeType') == 'text/plain' and part.get('body',{}).get('data'):
                body = part['body']['data']
                break
            elif part.get('mimeType') == 'multipart/alternative' and 'parts' in part:
                for p in part['parts']:
                    if p.get('mimeType') == 'text/plain' and p.get('body',{}).get('data'):
                        body = p['body']['data']
                        break
    elif msg['payload'].get('body',{}).get('data'):
        body = msg['payload']['body']['data']
    import base64
    if body:
        body_text = base64.urlsafe_b64decode(body).decode('utf-8', errors='replace')
        print(f\"Body: {body_text[:3000]}\")
    print('---MSG END---')
" 2>/dev/null
  echo "=== THREAD END ==="
done", "timeout": 60}

