import sys, json, base64
data = json.load(sys.stdin)
for msg in data.get('messages', []):
    headers = {h['name']: h['value'] for h in msg['payload']['headers']}
    print(f\"From: {headers.get('From','')}\")
    print(f\"To: {headers.get('To','')}\")
    print(f\"Subject: {headers.get('Subject','')}\")
    print(f\"Date: {headers.get('Date','')}\")
    # Try all possible body locations
    def extract_body(payload):
        if payload.get('body',{}).get('data'):
            return payload['body']['data']
        if 'parts' in payload:
            for part in payload['parts']:
                if part.get('mimeType') == 'text/plain' and part.get('body',{}).get('data'):
                    return part['body']['data']
                if part.get('mimeType') in ('multipart/alternative','multipart/mixed','multipart/related'):
                    result = extract_body(part)
                    if result:
                        return result
        return ''
    body = extract_body(msg['payload'])
    if body:
        body_text = base64.urlsafe_b64decode(body).decode('utf-8', errors='replace')
        print(f\"Body:\n{body_text}\")
    else:
        # Try snippet
        print(f\"Snippet: {msg.get('snippet','')}\")
    print('---MSG END---')
" 2>/dev/null
  echo "=== THREAD END ==="
done

